<?php
require_once __DIR__ . '/../includes/functions.php';
if (is_logged_in()) { header('Location: ' . BASE_URL . '/index.php'); exit; }
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $username=trim($_POST['username']??''); $password=$_POST['password']??''; $stmt=$pdo->prepare('SELECT id,nama,username,password,level FROM users WHERE username=? LIMIT 1'); $stmt->execute([$username]); $u=$stmt->fetch(); if($u && password_verify($password,$u['password'])) { session_regenerate_id(true); $_SESSION['user_id']=$u['id']; $_SESSION['nama']=$u['nama']; $_SESSION['username']=$u['username']; $_SESSION['level']=(int)$u['level']; header('Location: ' . BASE_URL . '/index.php'); exit; } $error='Username atau password salah.'; }
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login</title><link rel="stylesheet" href="<?= BASE_URL ?>/assets/style.css"></head><body><div class="login-wrap card"><h2>Login Sistem Penjualan</h2><p class="muted">Masuk menggunakan akun Owner atau Kasir.</p><?php if($error): ?><div class="alert"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Username</label><input name="username" required autofocus><label>Password</label><input type="password" name="password" required><button type="submit">Login</button></form><hr><p class="small muted">Demo: owner / owner123 &nbsp; | &nbsp; kasir / kasir123</p></div></body></html>
